-- Identity documents of active staff: latest expiry per employee, residence documents (RES) and passports (PASSPORT). Columns: tp, b, n
-- Buckets: EXPIRED, D30, D90, D180, OK, NOEXP (no document or no expiry date). Dates {D30}, {D90}, {D180} are as-of + 30/90/180 days.
-- LESSON (12 Oct 2026): taking MAX expiry over ALL document types let a valid passport hide an expired iqama. Keep the groups apart.
SELECT x.TP, CASE WHEN x.EXP IS NULL THEN 'NOEXP' WHEN x.EXP<DATE '{ASOF}' THEN 'EXPIRED' WHEN x.EXP<DATE '{D30}' THEN 'D30' WHEN x.EXP<DATE '{D90}' THEN 'D90' WHEN x.EXP<DATE '{D180}' THEN 'D180' ELSE 'OK' END B, COUNT(*) N FROM (SELECT c.STAFF_ID, 'RES' TP, (SELECT MAX(i.ID_WHEN_EXPIRED) FROM {P}PS_STAFF_IDS i WHERE i.STAFF_ID=c.STAFF_ID AND i.ID_TYPE_CODE IN ({ID_RES})) EXP FROM {P}PS_STAFF_CONTRACT c WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y' UNION ALL SELECT c.STAFF_ID, 'PASSPORT', (SELECT MAX(i.ID_WHEN_EXPIRED) FROM {P}PS_STAFF_IDS i WHERE i.STAFF_ID=c.STAFF_ID AND i.ID_TYPE_CODE IN ({ID_PASS})) FROM {P}PS_STAFF_CONTRACT c WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y') x GROUP BY x.TP, CASE WHEN x.EXP IS NULL THEN 'NOEXP' WHEN x.EXP<DATE '{ASOF}' THEN 'EXPIRED' WHEN x.EXP<DATE '{D30}' THEN 'D30' WHEN x.EXP<DATE '{D90}' THEN 'D90' WHEN x.EXP<DATE '{D180}' THEN 'D180' ELSE 'OK' END ORDER BY 1,2
